// build.ts — paragraph/run construction helpers shared by all exporters.
// Every property block (pPr inner, rPr inner) is captured verbatim from the
// template, so output formatting is identical to the original by construction.

import { xmlEscape, parseParagraphs, type Para } from "./ooxml.ts";

export interface RunSpec {
  rPrInner: string; // inner XML of <w:rPr> to clone
  text: string;
  preserveSpace?: boolean; // emit xml:space="preserve"
  breakBefore?: boolean; // emit <w:br/> before the text (within same run grouping)
  hyperlinkRid?: string; // wrap run in <w:hyperlink r:id="...">
}

export function makeRun(spec: RunSpec): string {
  const rpr = spec.rPrInner.trim() ? `<w:rPr>${spec.rPrInner}</w:rPr>` : "";
  const space =
    spec.preserveSpace || /^\s|\s$/.test(spec.text) ? ' xml:space="preserve"' : "";
  const br = spec.breakBefore ? "<w:br/>" : "";
  const t = spec.text === "" && !spec.breakBefore ? "" : `<w:t${space}>${xmlEscape(spec.text)}</w:t>`;
  const inner = `${rpr}${br}${t}`;
  const run = `<w:r>${inner}</w:r>`;
  if (spec.hyperlinkRid) {
    return `<w:hyperlink r:id="${spec.hyperlinkRid}" w:history="1">${run}</w:hyperlink>`;
  }
  return run;
}

export function makePara(pPrInner: string, runs: RunSpec[]): string {
  const ppr = pPrInner.trim() ? `<w:pPr>${pPrInner}</w:pPr>` : "";
  const body = runs.map(makeRun).join("");
  return `<w:p>${ppr}${body}</w:p>`;
}

// Replace the <w:body>…</w:body> inner content while preserving the body's
// trailing <w:sectPr> (the document-final section properties) unless the
// generated content supplies its own.
export function replaceBody(
  documentXml: string,
  newBodyInner: string
): string {
  return documentXml.replace(
    /(<w:body>)[\s\S]*(<\/w:body>)/,
    (_m, open, close) => `${open}${newBodyInner}${close}`
  );
}

// Extract the document-final sectPr (the one that is a direct child of body,
// i.e. the last top-level <w:sectPr> not inside a <w:p>).
export function finalSectPr(documentXml: string): string {
  // The body-level sectPr is the last <w:sectPr>…</w:sectPr> that appears
  // after the last </w:p>.
  const lastP = documentXml.lastIndexOf("</w:p>");
  const tail = lastP >= 0 ? documentXml.slice(lastP) : documentXml;
  const m = tail.match(/<w:sectPr\b[\s\S]*?<\/w:sectPr>/);
  return m ? m[0] : "";
}

// Capture the pPr inner XML of a representative paragraph matching a predicate.
export function findArchetype(
  paras: Para[],
  pred: (p: Para) => boolean
): Para | undefined {
  return paras.find(pred);
}

// Pull the dominant run's rPr inner from a paragraph (first run with text,
// else first run).
export function dominantRpr(p: Para): string {
  const r = p.runs.find((x) => x.text.trim()) ?? p.runs[0];
  return r ? r.rPrXml : "";
}

export { parseParagraphs };

// inline.ts — minimal, dependency-free inline markdown → run segments.
// Supports **bold**, *italic* / _italic_, and literal text. Markers are only
// honoured when balanced; otherwise the characters are treated literally so we
// never corrupt prose containing stray asterisks.

export interface Seg {
  text: string;
  bold: boolean;
  italic: boolean;
}

export function parseInline(src: string): Seg[] {
  const segs: Seg[] = [];
  let i = 0;
  let bold = false;
  let italic = false;
  let buf = "";
  const push = () => {
    if (buf) segs.push({ text: buf, bold, italic });
    buf = "";
  };
  while (i < src.length) {
    const two = src.slice(i, i + 2);
    const ch = src[i];
    if (two === "**" && hasCloser(src, i + 2, "**")) {
      push();
      bold = !bold;
      i += 2;
      continue;
    }
    if ((ch === "*" || ch === "_") && hasCloser(src, i + 1, ch)) {
      push();
      italic = !italic;
      i += 1;
      continue;
    }
    buf += ch;
    i += 1;
  }
  push();
  return segs.length ? segs : [{ text: src, bold: false, italic: false }];
}

function hasCloser(src: string, from: number, marker: string): boolean {
  return src.indexOf(marker, from) !== -1;
}

// Merge bold/italic flags into a base rPr inner XML by appending toggles.
export function applyToggles(baseRpr: string, seg: Seg): string {
  let rpr = baseRpr;
  // Insert toggles right after rStyle/rFonts if present, else prepend.
  const extra =
    (seg.bold ? "<w:b/><w:bCs/>" : "") + (seg.italic ? "<w:i/><w:iCs/>" : "");
  if (!extra) return rpr;
  // Avoid duplicating an existing <w:b/> etc.
  let add = extra;
  if (/<w:b\/>|<w:b\s/.test(rpr)) add = add.replace("<w:b/><w:bCs/>", "");
  if (/<w:i\/>|<w:i\s/.test(rpr)) add = add.replace("<w:i/><w:iCs/>", "");
  return rpr + add;
}

// coverletter.ts — regenerate a cover letter's body from markdown using the
// template's exact paragraph/run formatting.
//
// Markdown contract (a .md file):
//   - Paragraphs separated by blank lines.
//   - A single newline inside a paragraph becomes a line break (<w:br/>) — used
//     for the "Yours sincerely,\nNicholas Wood" sign-off.
//   - Inline **bold** and *italic* supported.
//   - Leading vertical spacers are taken from the template (not the markdown).

import { partText, setPart, parseParagraphs, type Para } from "./ooxml.ts";
import { makePara, replaceBody, type RunSpec } from "./build.ts";
import { parseInline, applyToggles } from "./inline.ts";
import type { Entries } from "./ooxml.ts";

export interface CoverArchetypes {
  spacerPpr: string; // pPr inner of a leading empty paragraph
  bodyPpr: string; // pPr inner of a body paragraph
  bodyRpr: string; // rPr inner of a body run
  leadingSpacers: number; // count of leading empty paragraphs in template
  finalSectPr: string; // body-final sectPr (empty for cover letter — uses default)
}

export function captureCoverArchetypes(entries: Entries): CoverArchetypes {
  const doc = partText(entries, "word/document.xml");
  const paras = parseParagraphs(doc);
  // Leading empty paragraphs = spacers.
  let leadingSpacers = 0;
  while (leadingSpacers < paras.length && !paras[leadingSpacers].text.trim())
    leadingSpacers++;
  const firstBody = paras.find((p) => p.text.trim());
  if (!firstBody) throw new Error("cover template has no body paragraph");
  const bodyRun = firstBody.runs.find((r) => r.text.trim()) ?? firstBody.runs[0];
  const spacerPara = paras[0];
  // body-final sectPr lives inside the LAST paragraph's pPr or at body end
  const last = paras[paras.length - 1];
  const sectMatch = last.pPrXml.match(/<w:sectPr\b[\s\S]*?<\/w:sectPr>/);
  // For the cover letter the sectPr is a direct child of body (self-contained).
  const bodySect = doc.match(/<\/w:p>\s*(<w:sectPr\b[\s\S]*?<\/w:sectPr>)/);
  return {
    spacerPpr: spacerPara.pPrXml,
    bodyPpr: firstBody.pPrXml,
    bodyRpr: bodyRun?.rPrXml ?? "",
    leadingSpacers,
    finalSectPr: (sectMatch?.[0] ?? bodySect?.[1] ?? ""),
  };
}

// Split markdown into content paragraphs (blocks separated by blank lines).
export function splitParagraphs(md: string): string[] {
  const norm = md.replace(/\r\n?/g, "\n").trim();
  // Drop an optional leading markdown H1 title and any HTML comments.
  const cleaned = norm
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/^#\s.*$/m, "")
    .trim();
  return cleaned
    .split(/\n\s*\n/)
    .map((b) => b.trim())
    .filter((b) => b.length > 0);
}

export function exportCoverLetter(entries: Entries, md: string): Entries {
  const a = captureCoverArchetypes(entries);
  const blocks = splitParagraphs(md);

  const out: string[] = [];
  // Leading spacers, verbatim from template formatting.
  for (let i = 0; i < a.leadingSpacers; i++) out.push(makePara(a.spacerPpr, []));

  for (const block of blocks) {
    const lines = block.split("\n");
    const runs: RunSpec[] = [];
    lines.forEach((line, li) => {
      const segs = parseInline(line);
      segs.forEach((seg, si) => {
        runs.push({
          rPrInner: applyToggles(a.bodyRpr, seg),
          text: seg.text,
          breakBefore: li > 0 && si === 0, // line break between wrapped lines
          preserveSpace: true,
        });
      });
    });
    out.push(makePara(a.bodyPpr, runs));
  }

  const sect = a.finalSectPr ? a.finalSectPr : "";
  const doc = partText(entries, "word/document.xml");
  const newDoc = replaceBody(doc, out.join("") + sect);
  setPart(entries, "word/document.xml", newDoc);
  return entries;
}

// export.ts — CLI entry. Template-surgery md -> docx exporter.
//
// Usage:
//   bun src/export.ts coverletter <input.md> <output.docx> [--template <docx>]
//   bun src/export.ts resume      <input.md> <output.docx> [--template <docx>]
//
// The output reuses the template's styles, theme, fonts, settings (ligatures),
// numbering, headers/footers and page setup byte-for-byte; only the document
// body is regenerated from the markdown.

import { dirname, resolve } from "path";
import { fileURLToPath } from "url";
import { readDocx, writeDocx } from "./ooxml.ts";
import { exportCoverLetter } from "./coverletter.ts";
import { exportResume } from "./resume.ts";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
}

const type = process.argv[2];
const input = process.argv[3];
const output = process.argv[4];

if (!type || !input || !output || !["coverletter", "resume"].includes(type)) {
  console.error(
    "usage: bun src/export.ts <coverletter|resume> <input.md> <output.docx> [--template <docx>]"
  );
  process.exit(1);
}

const template =
  arg("--template") ?? resolve(ROOT, "profiles", `${type}.template.docx`);

const md = require("fs").readFileSync(resolve(input), "utf8");
const entries = readDocx(template);

const result =
  type === "coverletter"
    ? exportCoverLetter(entries, md)
    : exportResume(entries, md);

writeDocx(resolve(output), result);
console.log(`✓ wrote ${output} (from ${type} template: ${template})`);

// resume.ts — placeholder; full implementation follows after cover-letter path
// is proven exact.
import type { Entries } from "./ooxml.ts";
export function exportResume(_entries: Entries, _md: string): Entries {
  throw new Error("resume exporter not yet implemented");
}

